/* Scripted onboarding preview. No OAuth, mailbox access or purchase occurs. */
const onboardingScreens=['Welcome','Connect inbox','Discovering','Your subscriptions','Ready to go','Scan · no results','Scan · interrupted'];
const ob={selected:new Set([0,1,2]),timers:[],scan:0,account:false,accountEmail:'',accountId:'',provider:'',gmailConsent:false,inboxEmail:'',connectionMessage:'',importSaved:false,savedSelection:null,pendingIntent:''};
const obItems=[['Netflix','N','15.99','USD','27 Oct','Entertainment','2026-10-27'],['Spotify','S','11.99','USD','31 Oct','Music','2026-10-31',{trial:true,start:'2026-10-24',trialDays:7,autoRenew:true,trialEndSource:'exact'}],['iCloud+','☁','2.99','USD','30 Oct','Storage','2026-10-30']];
// Stable synthetic candidate IDs; production uses backend-owned candidate IDs.
const obCandidateIds=['scan-netflix','scan-spotify','scan-icloud'];
const obDrafts=new Map();
function obToday(){return typeof calendarToday==='string'?calendarToday:'2026-10-27';}
function obDate(value){if(!value)return 'Date not set';return new Date(value+'T00:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});}
function obCandidates(){return obItems.map(([name,mark,price,currency,date,category,event,trial],i)=>({id:obCandidateIds[i],name,price,currency,category,cycle:'Monthly',renewal:event,estimated:!trial?.trial,source:'Gmail',inboxEmail:ob.inboxEmail||obGoogleFixture.email,trial:!!trial?.trial,...(trial?.trial?{start:trial.start,trialDays:trial.trialDays,trialEnd:event,trialEndSource:'exact',autoRenew:trial.autoRenew}:{}),...obDrafts.get(obCandidateIds[i])})).map(r=>typeof trackedRecord==='function'?trackedRecord(r):r);}
function obChosen(indices=obSavedIndices(ob)){return obCandidates().filter((r,i)=>indices.includes(i));}
function obMonthlyTotals(records){const sums={};for(const r of records){if(r.trial)continue;const amount=Math.round(Number(r.price)*100),factor={Weekly:52/12,Monthly:1,Quarterly:1/3,Yearly:1/12}[r.cycle];if(!Number.isFinite(amount)||amount<0||!factor)continue;sums[r.currency]=(sums[r.currency]||0)+amount*factor;}if(!Object.keys(sums).length)for(const r of records)if(r.trial)sums[r.currency]=0;return Object.fromEntries(Object.entries(sums).map(([c,v])=>[c,Math.round(v)/100]));}
function obMoney(totals){return Object.entries(totals).map(([c,v])=>`${escape(c)} ${v.toFixed(2)}`).join(' · ')||'—';}
function obEvents(records,today=obToday()){const start=Date.parse(today+'T00:00:00Z'),end=start+6*86400000;return records.map(r=>({...r,eventDate:r.trial?r.trialEnd:r.renewal})).filter(r=>r.eventDate&&Date.parse(r.eventDate+'T00:00:00Z')>=start&&Date.parse(r.eventDate+'T00:00:00Z')<=end).sort((a,b)=>a.eventDate.localeCompare(b.eventDate)||a.id.localeCompare(b.id));}
function obUpcoming(){const events=obEvents(obChosen()),totals={};for(const r of events){if(r.trial&&r.autoRenew!==true)continue;totals[r.currency]=(totals[r.currency]||0)+Math.round(Number(r.price)*100);}return `<section class="ob-renewal-line" aria-label="Upcoming renewals and trial endings"><span><strong>${events.length} upcoming ${events.length===1?'renewal':'renewals'}</strong> in 7 days</span><span class="ob-renewal-amount">${obMoney(Object.fromEntries(Object.entries(totals).map(([c,v])=>[c,v/100])))}</span></section>`;}
function onboardingTrackedRecords(){return ob.dashboardActive?Object.values(ob.savedRecords||{}).map(r=>({...r})):null;}
// Only synthetic Studio state is stored. Never use this storage for real auth/tokens/mail/media.
function obPersist(){try{if(typeof sessionStorage==='undefined')return;sessionStorage.setItem('renewless-onboarding-preview-v2',JSON.stringify({version:2,account:!!ob.account,firstName:ob.firstName||'',grant:!!ob.gmailConsent,stage:ob.stage||'Connect inbox',scan:ob.scan,scanStarted:!!ob.scanStarted,selected:obSavedIndices(ob).map(i=>obCandidateIds[i]),drafts:[...obDrafts],savedRecords:ob.savedRecords||{},dashboardActive:!!ob.dashboardActive,complete:!!ob.complete,saved:Object.keys(ob.savedRecords||{}).map(id=>obCandidateIds.indexOf(id)).filter(i=>i>=0)}));}catch(error){}}
function obRestore(){try{if(typeof sessionStorage==='undefined')return;const data=JSON.parse(sessionStorage.getItem('renewless-onboarding-preview-v2')||'null');if(data?.version!==2||typeof data.account!=='boolean')return;for(const [id,draft]of data.drafts||[]){if(!obCandidateIds.includes(id)||typeof draft!=='object')continue;const safe={};for(const key of ['price','currency','cycle','renewal','trialEnd','trialDays','estimated'])if(['string','number','boolean'].includes(typeof draft[key]))safe[key]=draft[key];obDrafts.set(id,safe);}ob.selected=new Set((data.selected||[]).map(id=>obCandidateIds.indexOf(id)).filter(i=>i>=0));if(data.account)Object.assign(ob,obGoogleOutcome(ob,obGoogleFixture).state);ob.firstName=typeof data.firstName==='string'?data.firstName:'';ob.gmailConsent=data.account&&data.grant===true;ob.inboxEmail=ob.gmailConsent?obGoogleFixture.email:'';ob.stage=onboardingScreens.includes(data.stage)?data.stage:'Connect inbox';ob.scan=Math.max(0,Math.min(3,Number(data.scan)||0));ob.scanStarted=!!(data.account&&data.grant&&data.scanStarted);ob.complete=!!data.complete;ob.dashboardActive=!!data.dashboardActive;ob.savedSelection=(data.saved||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<obItems.length);ob.importSaved=ob.savedSelection.length>0;ob.savedRecords={};for(const base of obChosen(ob.savedSelection)){const saved=data.savedRecords?.[base.id];if(!saved||!Number.isFinite(Number(saved.price))||Number(saved.price)<0)continue;const r={...base};for(const key of ['price','currency','cycle','renewal','start','trial','trialEnd','trialDays','trialEndSource','autoRenew','estimated'])if(['string','number','boolean'].includes(typeof saved[key]))r[key]=saved[key];ob.savedRecords[r.id]=r;}}catch(error){}}
function obResumeTarget(fallback){if(!ob.account)return fallback;if(ob.complete)return 'Home';return ob.gmailConsent?ob.stage||'Discovering':'Connect inbox';}
function obSkipSave(){if(!ob.account){go('Connect inbox');return;}ob.dashboardActive=true;ob.savedRecords=ob.savedRecords||{};ob.complete=true;ob.stage='Home';obPersist();go('Home');}
function obMascot(expression,size){return mascotView({expression,size,artworkScale:1,halo:false,draw:ob.lastFrame!==current,label:expression==='sad'?'Loop is here to help':expression==='happy'?'Loop celebrates your saved subscriptions':'Loop is finding subscriptions'});}
function obTop(n,back='Welcome'){return `<div class="ob-top">${current==='Welcome'?'<span class="ob-back"></span>':btn('‹',back,'ob-back')}<span>RENEWLESS</span><img src="assets/renewless-mark.svg" alt=""></div><div class="ob-steps" aria-label="Step ${n} of 5">${[1,2,3,4,5].map(i=>`<i class="${i<=n?'done':''}"></i>`).join('')}</div>`;}
function obTitle(tag,title,copy){return `<div class="ob-intro"><p class="eyebrow">${tag}</p><h2>${title}</h2><p>${copy}</p></div>`;}
function obScene(){return `<div class="ob-scene" aria-label="An email receipt becomes an organized subscription"><div class="ob-orbit"></div><div class="ob-receipt"><span>✉ &nbsp; YOUR INBOX</span><strong>Your monthly receipt</strong><i></i><i></i><b>$15.99</b></div><div class="ob-found"><span class="ob-service">${platformLogo('Netflix')}</span><div><strong>Netflix</strong><small>Monthly · renews Oct 27</small></div><b>$15.99</b></div><div class="ob-pill">✓ &nbsp; Renewal found</div><img class="ob-loop" src="assets/loop-mascot.svg" alt="Loop"></div>`;}
// Explicit fixture outcome only: production must verify identity/session and granted Gmail scopes server-side.
const obGoogleFixture={signedIn:true,accountId:'preview-account-alex',subject:'preview-google-alex',email:'alex@example.com',firstName:'Alex',gmailGranted:true};
function obGoogleOutcome(state,outcome){const next={...state,connectionMessage:''};if(outcome.signedIn!==true||!outcome.accountId||!outcome.email){next.connectionMessage=outcome.cancelled?'Sign-in was cancelled. You can try again or add subscriptions manually.':'We couldn’t sign you in. Try again or add subscriptions manually.';return {state:next,route:'Connect inbox'};}if(!next.account){next.account=true;next.accountId=outcome.accountId;next.accountEmail=outcome.email;next.firstName=outcome.firstName||'';next.provider='Google';}next.pending=false;next.pendingIntent='';if(outcome.gmailGranted!==true){next.gmailConsent=false;next.inboxEmail='';next.connectionMessage='You’re signed in. Allow Gmail access to scan, or add subscriptions manually.';return {state:next,route:'Connect inbox'};}next.gmailConsent=true;next.inboxEmail=outcome.email;next.googleSubject=outcome.subject||'';return {state:next,route:'Discovering'};}
function obSavedIndices(state){return [...state.selected].filter(index=>Number.isInteger(index)&&index>=0&&index<obItems.length).sort((a,b)=>a-b);}
function obFinishSave(indices=obSavedIndices(ob)){if(!ob.account||!indices.length)return false;ob.savedSelection=[...indices];if(!ob.dashboardActive)ob.priorRecordIds=typeof trialRecords!=='undefined'?[...trialRecords.keys()]:[];ob.savedRecords=ob.savedRecords||{};for(const r of obChosen(indices))ob.savedRecords[r.id]=r;ob.dashboardActive=true;ob.importSaved=true;ob.pending=false;obPersist();go('Ready to go');return true;}
function resetOnboardingConnection(){obDrafts.clear();try{if(typeof sessionStorage!=='undefined')sessionStorage.removeItem('renewless-onboarding-preview-v2');}catch(error){}Object.assign(ob,{selected:new Set([0,1,2]),savedRecords:{},priorRecordIds:[],connectEpoch:(ob.connectEpoch||0)+1,connecting:false,dashboardActive:false,complete:false,stage:'',scanStarted:false,lastFrame:'',saving:false,saveError:'',saveEpoch:(ob.saveEpoch||0)+1,firstName:'',account:false,accountEmail:'',accountId:'',provider:'',gmailConsent:false,inboxEmail:'',googleSubject:'',connectionMessage:'',importSaved:false,savedSelection:null,pendingIntent:'',pending:false,manualEntry:false,manualFormFromOnboarding:false});}
// Preview-only save delay: native production waits for the owned import response.
async function obSaveSelected(commit=()=>new Promise(resolve=>setTimeout(resolve,350))){
 if(ob.saving||!obSavedIndices(ob).length)return false;
 if(!ob.account){go('Connect inbox');return false;}
 const indices=obSavedIndices(ob),owner=ob.accountId,epoch=(ob.saveEpoch||0)+1;
 ob.saveEpoch=epoch;ob.saving=true;ob.saveError='';render();
 try{await commit(indices);if(ob.saveEpoch!==epoch||current!=='Your subscriptions'||!ob.account||ob.accountId!==owner)return false;ob.saving=false;return obFinishSave(indices);}
 catch(error){if(ob.saveEpoch===epoch&&current==='Your subscriptions'){ob.saving=false;ob.saveError='Couldn’t save your subscriptions. Please try again.';render();}return false;}
}
function onboarding(){
 let body='';
 if(current==='Welcome')body=obTop(1)+obScene()+obTitle('LESS GUESSWORK. MORE CONTROL.','Know what renews.<br><em>Before it does.</em>','Find subscriptions in your Gmail, understand their cost, and stay ahead of renewals.')+`<div class="ob-benefits"><span><svg class="ob-benefit-icon" viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/></svg><span class="ob-benefit-label">Find</span></span><span><svg class="ob-benefit-icon" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg><span class="ob-benefit-label">Track</span></span><span><svg class="ob-benefit-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM10 21h4"/></svg><span class="ob-benefit-label">Remember</span></span></div><div class="ob-bottom">${btn('Find my subscriptions →','Connect inbox')}${btn('Already have an account? Log in','Login','link')}</div>`;
 if(current==='Connect inbox')body=obTop(2)+`<div class="ob-connect-art" role="img" aria-label="Connect Gmail to Renewless"><div class="ob-connection-brand"><span class="ob-connection-tile">${platformLogo('Gmail')}</span><span class="ob-connection-label">Gmail</span></div><svg class="ob-connection-arrow" viewBox="0 0 48 24" aria-hidden="true"><path d="M4 12h38m-7-7 7 7-7 7"/></svg><div class="ob-connection-brand"><span class="ob-connection-tile"><img src="assets/renewless-mark.svg" alt=""></span><span class="ob-connection-label">Renewless</span></div></div>`+obTitle('START WITH YOUR INBOX','Less typing.<br><em>More tracking.</em>','Connect the Gmail account where you receive subscription receipts.')+`<p class="ob-signin-disclosure">${ob.account?'You’re already signed in. We’ll ask permission to find subscriptions in your Gmail.':'We’ll use this Google account to sign you in and ask permission to find subscriptions in your inbox.'}</p>${ob.connectionMessage?'<p class="ob-connection-feedback" role="alert">'+escape(ob.connectionMessage)+'</p>':''}<div class="ob-trust">${fr('Read-only access','We can’t send or delete emails')}${fr('You’re in control','Review before saving')}${fr('Scans & updates','Free to use')}</div>${infoTooltip({"id": "email-processing-info", "label": "How we use your email", "paragraphs": ["Google grants read access to your mailbox. Renewless filters relevant receipts and renewal emails from the last 12 months, then uses AI to extract subscription details.", "You can disconnect your inbox. Your permission is required before processing."], "className": "ob-email-info"})}<div class="ob-bottom"><button class="primary ob-google-connect" data-ob="connect-google" ${ob.connecting?'disabled':''} aria-busy="${!!ob.connecting}"><span>${ob.connecting?'Connecting…':'Connect Gmail and Login'}</span></button>${btn('Add subscriptions manually','Sign up','link')}<div class="ob-google-legal"><button type="button" data-action="legal">Terms</button><span>·</span><button type="button" data-action="legal">Privacy</button></div></div>`;
 if(current==='Discovering')body=obTop(3,'Connect inbox')+`<div class="ob-radar ob-discovery-art ${ob.scan===3?'is-complete':''}"><div></div>${obMascot('neutral',90)}</div>`+obTitle('A LITTLE CLARITY IS ON ITS WAY','Connecting the dots.','Turning your receipts into a clearer picture of your subscriptions.')+`<div class="ob-scan-stages" aria-live="polite">${['Finding receipts','Grouping subscriptions','Checking renewal details'].map((t,i)=>`<div class="${i<ob.scan?'done':i===ob.scan?'scanning':''}"><span>${i<ob.scan?'✓':'0'+(i+1)}</span>${t}</div>`).join('')}</div><div class="ob-bottom"><p class="note ob-scan-status" role="status">${ob.scan<3?'This may take a moment.':'Your results are ready.'}</p></div>`;
 if(current==='Your subscriptions'){const records=obCandidates(),total=obMoney(obMonthlyTotals(obChosen()));body=obTop(4,'Connect inbox')+obTitle('YOUR FIRST LOOK','Your subscriptions,<br><em>in one place.</em>',`We found ${records.length} possible subscriptions. Choose the ones you want to track.`)+`<p class="ob-inbox-context">Found in ${escape(ob.inboxEmail||obGoogleFixture.email)}</p><div class="ob-total"><div><small>Estimated monthly cost</small><strong>${total}</strong><span>Free trials aren’t included in this total.</span></div><div class="ob-donut" role="img" aria-label="${ob.selected.size} of ${records.length} subscriptions selected" style="--selection-fill:${records.length?ob.selected.size/records.length*100:0}%"><span>${ob.selected.size}/${records.length}</span></div></div>${obUpcoming()}<p class="ob-caption">SUBSCRIPTIONS FOUND <span>Review before saving</span></p><div class="ob-results">${records.map((r,i)=>`<div class="ob-result-row"><label><input type="checkbox" ${ob.saving?'disabled':''} data-ob-item="${i}" ${ob.selected.has(i)?'checked':''} aria-label="Select ${escape(r.name)}"><span class="ob-service service-${i}">${platformLogo(r.name)}</span><span><strong>${escape(r.name)}</strong><small>${r.trial?'Trial ends':'Renews'} ${obDate(r.trial?r.trialEnd:r.renewal)}${r.estimated?' · estimated':''}</small><small>${r.trial?'Then ':''}${escape(r.currency)} ${Number(r.price).toFixed(2)} · ${escape(r.cycle)}</small></span></label><button class="ob-edit-draft" data-ob-edit="${i}" aria-label="Edit ${escape(r.name)}" ${ob.saving?'disabled':''}><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z"/></svg></button></div>`).join('')}</div>${infoTooltip({id:'estimates-info',label:'How these estimates work',paragraphs:['Receipts may refer to older or cancelled plans. Review each subscription before saving. You can correct the amount and date with Edit.','Monthly cost averages paid billing cycles and excludes active free trials. Trial rows show the price after trial. Upcoming expected charges cover today and the next 6 calendar days. Currencies stay separate without conversion.'],className:'ob-estimates-info'})}<div class="ob-bottom">${ob.saveError?`<p class="ob-connection-feedback" role="alert">${escape(ob.saveError)}</p>`:''}<button class="primary" data-ob="save" aria-busy="${!!ob.saving}" ${ob.selected.size&&!ob.saving?'':'disabled'}>${ob.saving?'Saving…':`Save ${ob.selected.size} ${ob.selected.size===1?'subscription':'subscriptions'} →`}</button>${ob.selected.size?btn('Add a subscription manually','Sign up','link'):'<button class="link" data-ob="skip-save">Continue without saving</button>'}</div>`;}
 if(current==='Ready to go'){
 const savedIndices=ob.importSaved&&ob.savedSelection?new Set(ob.savedSelection):ob.selected;
 const saved=ob.importSaved?Object.values(ob.savedRecords||{}):obChosen([...savedIndices]);
 const totals=obMonthlyTotals(saved);
 const next=saved.map(r=>({...r,eventDate:r.trial?r.trialEnd:r.renewal})).filter(r=>r.eventDate&&r.eventDate>=obToday()).sort((a,b)=>a.eventDate.localeCompare(b.eventDate))[0];
 body=obTop(5,'Your subscriptions')+`<div class="ob-ready-confetti" aria-hidden="true"><span class="ob-party-popper ob-party-left">🎉</span><span class="ob-party-popper ob-party-right">🎉</span>${Array.from({length:60},(_,i)=>`<i style="--x:${4+(i*37)%92}%;--drift:${(i%2?1:-1)*(20+(i*13)%75)}px;--delay:${.42+Math.floor(i/2)*.009}s;--travel:${440+(i*31)%190}px;--spread:${35+(i*23)%230}px;--turn:${180+(i*53)%540}deg;--color:${['#B9E58C','#E8EAED','#849B76','#E8BE78'][i%4]}"></i>`).join('')}</div><div class="ob-ready-celebration"><div class="ob-ready-halo"></div><div class="ob-ready-mascot">${obMascot('happy',120)}</div><span aria-hidden="true"><svg viewBox="0 0 24 24"><path d="m6 12 4 4 8-9"/></svg></span></div>`+obTitle('A LITTLE LESS TO REMEMBER',ob.firstName?`You’re all set,<br><em>${escape(ob.firstName)}.</em>`:'You’re all set.','Your subscriptions are together. Your next renewal is easier to keep track of.')+`<section class="ob-ready-summary"><div><strong>${saved.length}</strong><span>${saved.length===1?'subscription saved':'subscriptions saved'}</span></div><div><strong>${obMoney(totals)}</strong><span>Estimated monthly cost</span></div></section>${next?`<section class="ob-ready-next"><span class="ob-service">${platformLogo(next.name)}</span><div><small>${next.trial?'NEXT TRIAL ENDING':next.estimated?'NEXT ESTIMATED RENEWAL':'NEXT RENEWAL'}</small><strong>${escape(next.name)}</strong><span>${obDate(next.eventDate)} · ${escape(next.currency)} ${Number(next.price).toFixed(2)}${next.trial?' after trial':''}</span></div></section>`:'<p class="ob-ready-empty">Add a renewal date to see what’s coming next.</p>'}<p class="ob-ready-reminder">Set reminders and stay ahead of your next renewal.</p><div class="ob-bottom"><button class="primary" data-ob="dashboard">Go to my dashboard →</button></div>`;
 }
 if(current==='Scan · no results')body=obTop(3,'Connect inbox')+`<div class="ob-empty-art"><div class="ob-mascot-art">${obMascot('sad',150)}</div><span aria-hidden="true"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/></svg></span></div>`+obTitle('YOUR INBOX, CHECKED','No subscriptions<br><em>found this time.</em>','We didn’t find subscription receipts in this inbox from the last 12 months.')+`<section class="ob-empty-hint"><span class="ob-empty-hint-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M9 18h6m-5 3h4M8 14a6 6 0 1 1 8 0c-1 1-1 2-1 2H9s0-1-1-2Z"/></svg></span><div><h3>Using another email for payments?</h3><p>Your receipts may be in a different inbox. Try the Gmail account you use for subscriptions.</p></div></section><p class="ob-empty-reassurance">You can still track any subscription by adding it yourself.</p><div class="ob-bottom">${btn('Try another Gmail account','Connect inbox')}${btn('Add a subscription manually','Sign up','secondary')}</div>`;
 if(current==='Scan · interrupted')body=obTop(3,'Connect inbox')+`<div class="ob-empty-art"><div class="ob-mascot-art">${obMascot('sad',150)}</div><span aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 9a13 13 0 0 1 16 0M7 12a8 8 0 0 1 10 0M10 15a3 3 0 0 1 4 0M12 19h.01M3 3l18 18"/></svg></span></div>`+obTitle('LET’S GET BACK ON TRACK','Your scan<br><em>was interrupted.</em>',ob.interruptionReason==='access'?'Gmail access needs to be renewed before we can continue.':'We couldn’t finish checking your inbox. Check your connection and try again.')+`<section class="ob-empty-hint"><span class="ob-empty-hint-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-1l2 6M4 12l2 6a7 7 0 0 0 12-1"/></svg></span><div><h3>A quick check before retrying</h3><p>Check your internet connection. If Google asks, allow read-only Gmail access so we can complete your scan.</p></div></section><p class="ob-empty-reassurance">You can also add subscriptions yourself and connect your inbox later.</p><div class="ob-bottom"><button class="primary" data-ob="retry-scan">${ob.interruptionReason==='access'?'Reconnect Gmail':'Try again'}</button>${btn('Add a subscription manually','Sign up','secondary')}</div>`;
 // Keep navigation and actions outside the independently scrolling content.
 const layout=document.createElement('template');layout.innerHTML=body;
 const top=layout.content.querySelector('.ob-top'),steps=layout.content.querySelector('.ob-steps'),footer=layout.content.querySelector('.ob-bottom');
 const headerHTML=(top?.outerHTML||'')+(steps?.outerHTML||'');top?.remove();steps?.remove();footer?.remove();
 const account=layout.content.querySelector('.ob-account');
 if(account&&footer){footer.prepend(account);const note=layout.content.querySelector(':scope > .note');if(note)footer.append(note);}
 const content=document.createElement('div');content.append(layout.content);
 return `<div class="ob-page"><header class="ob-fixed-top">${headerHTML}</header><div class="ob-scroll" tabindex="0" role="region" aria-label="${current} content">${content.innerHTML}</div>${footer?.outerHTML||''}</div>`;
}
function onboardingAfterRender(){
 ob.timers.forEach(clearTimeout);ob.timers=[];
 document.querySelectorAll('.ob-ready-confetti').forEach(overlay=>{const phone=overlay.closest('.phone');if(phone)phone.append(overlay);});
 ob.lastFrame=current;
 if(onboardingScreens.includes(current)){ob.stage=current;obPersist();}
 if(current==='Splash')ob.timers.push(setTimeout(()=>go('Welcome'),2600));
 if(current==='Discovering'){
  if(ob.scan<3)ob.timers.push(setTimeout(()=>{ob.scan++;obPersist();render();},1100));
  else ob.timers.push(setTimeout(()=>go('Your subscriptions'),650));
 }
}
async function obConnect(outcome=obGoogleFixture){if(ob.connecting)return;const epoch=(ob.connectEpoch||0)+1;ob.connectEpoch=epoch;ob.connecting=true;render();await new Promise(r=>setTimeout(r,350));if(ob.connectEpoch!==epoch||current!=='Connect inbox')return;ob.connecting=false;const reusable=ob.scanStarted&&ob.gmailConsent&&ob.inboxEmail===outcome.email;const result=obGoogleOutcome(ob,outcome);Object.assign(ob,result.state);if(result.route==='Discovering'){if(reusable){ob.resumeScan=true;if(ob.scan===3)result.route='Your subscriptions';}else{ob.scanStarted=true;ob.scan=0;}}obPersist();go(result.route);}
function obRetryScan(){if(ob.interruptionReason==='access'||!ob.gmailConsent)go('Connect inbox');else{ob.resumeScan=true;go('Discovering');}}
function obCloseReview(){const dialog=document.querySelector('.ob-review-dialog');if(!dialog)return;const index=dialog.dataset.index;closeSelectMenu(false);dialog.remove();document.querySelector('#upgraded .content').inert=false;document.querySelector(`[data-ob-edit="${index}"]`)?.focus();}
function obOpenReview(index){if(ob.saving)return;const r=obCandidates()[index];if(!r)return;const dialog=document.createElement('div');dialog.className='detail-dialog-overlay ob-review-dialog';dialog.dataset.index=index;dialog.innerHTML=`<div class="track-again-shade" data-ob-close-edit></div><section class="track-again-sheet" role="dialog" aria-modal="true" aria-labelledby="ob-edit-title"><div class="handle"></div><header><div><h3 id="ob-edit-title">Review ${escape(r.name)}</h3><p>Changes apply when you save your subscriptions.</p></div><button data-ob-close-edit aria-label="Close review">×</button></header><form data-ob-review="${index}"><div class="manual-price-row"><label>${r.trial?'Price after trial':'Amount'}<input name="price" type="number" required min="0" step="0.01" value="${escape(r.price)}"></label>${selectField({label:'Currency',name:'currency',options:['USD','EUR','GBP','PKR','AED','INR'],value:r.currency})}</div>${selectField({label:'Billing cycle',name:'cycle',options:['Monthly','Quarterly','Yearly','Weekly'],value:r.cycle})}<label>${r.trial?'Trial end':'Next renewal · Optional'}<input name="eventDate" type="date" value="${escape(r.trial?r.trialEnd:r.renewal||'')}" ${r.trial?'required min="'+escape(r.start)+'"':''}></label><button class="primary" type="submit">Update details</button></form></section>`;document.getElementById('upgraded').append(dialog);document.querySelector('#upgraded .content').inert=true;dialog.querySelector('input').focus();}
document.addEventListener('click',e=>{if(e.target.closest('[data-ob-close-edit]')){obCloseReview();return;}const edit=e.target.closest('[data-ob-edit]');if(edit){obOpenReview(Number(edit.dataset.obEdit));return;}const b=e.target.closest('[data-ob]');if(!b)return;if(b.dataset.ob==='connect-google')obConnect();else if(b.dataset.ob==='save')obSaveSelected();else if(b.dataset.ob==='skip-save')obSkipSave();else if(b.dataset.ob==='dashboard'){ob.complete=true;ob.stage='Home';obPersist();go('Home');}else if(b.dataset.ob==='retry-scan')obRetryScan();});
document.addEventListener('change',e=>{if(!e.target.matches('[data-ob-item]')||ob.saving)return;const i=Number(e.target.dataset.obItem);if(e.target.checked)ob.selected.add(i);else ob.selected.delete(i);const scroller=document.querySelector('.ob-scroll'),top=scroller?.scrollTop||0;obPersist();render();document.querySelector('.ob-scroll').scrollTop=top;document.querySelector(`[data-ob-item="${i}"]`)?.focus({preventScroll:true});});
document.addEventListener('submit',e=>{const form=e.target.closest('[data-ob-review]');if(!form)return;e.preventDefault();e.stopImmediatePropagation();if(!form.reportValidity())return;const i=Number(form.dataset.obReview),r=obCandidates()[i],price=Number(form.elements.price.value);if(!r||!Number.isFinite(price)||price<0)return;const date=form.elements.eventDate.value,draft={price:price.toFixed(2),currency:form.elements.currency.value,cycle:form.elements.cycle.value,estimated:date!==(r.trial?r.trialEnd:r.renewal)?false:r.estimated};if(r.trial){draft.trialEnd=date;draft.renewal=date;draft.trialDays=Math.round((Date.parse(date)-Date.parse(r.start))/86400000);}else draft.renewal=date;obDrafts.set(r.id,draft);obCloseReview();obPersist();render();document.querySelector(`[data-ob-edit="${i}"]`)?.focus();},true);
document.addEventListener('keydown',e=>{const d=document.querySelector('.ob-review-dialog');if(!d)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();if(typeof activeSelect!=='undefined'&&activeSelect)closeSelectMenu();else obCloseReview();}else if(e.key==='Tab'){const controls=[...d.querySelectorAll('button,input')].filter(el=>!el.closest('[hidden]')&&!el.disabled),first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}},true);
